/// <summary>
///
/// </summary>
public static METSalesOrderShipmentLoadHeader findOrCreateOpenShipment(CustAccount                    _custAccount,
                                                                      METRoute                        _metRoute,
                                                                      METRouteStopNum                 _metRouteStop,
                                                                      SalesShippingDateConfirmed      _confirmedDate,
                                                                      InventLocationId                _inventLocationId,
                                                                      MetOrderTransactionType         _transactionType)
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;

    select firstonly metSalesOrderShipmentLoadHeader
        where metSalesOrderShipmentLoadHeader.CustAccount == _custAccount       &&
            metSalesOrderShipmentLoadHeader.Route == _metRoute                  &&
            metSalesOrderShipmentLoadHeader.RouteStopNum == _metRouteStop       &&
            metSalesOrderShipmentLoadHeader.ConfirmedShipDate == _confirmedDate &&
            metSalesOrderShipmentLoadHeader.Warehouse == _inventLocationId      &&
            metSalesOrderShipmentLoadHeader.ShipmentStatus == MetShipmentStatus::Open;

    if (metSalesOrderShipmentLoadHeader.RecId != 0)
    {
        return metSalesOrderShipmentLoadHeader;
    }

    metSalesOrderShipmentLoadHeader.clear();

    metSalesOrderShipmentLoadHeader.ShipmentId = NumberSeq::newGetNum(InventParameters::numRefMetShippingID()).num();
    metSalesOrderShipmentLoadHeader.CustAccount = _custAccount;
    metSalesOrderShipmentLoadHeader.ConfirmedShipDate = _confirmedDate;
    metSalesOrderShipmentLoadHeader.Route = _metRoute;
    metSalesOrderShipmentLoadHeader.RouteStopNum = _metRouteStop;
    metSalesOrderShipmentLoadHeader.Warehouse = _inventLocationId;
    metSalesOrderShipmentLoadHeader.SiteId = InventLocation::find(_inventLocationId).InventSiteId;
    metSalesOrderShipmentLoadHeader.TransactionType = _transactionType;
    metSalesOrderShipmentLoadHeader.ShipmentStatus = MetShipmentStatus::Open;
    metSalesOrderShipmentLoadHeader.ShipmentCarrier = '';
    metSalesOrderShipmentLoadHeader.insert();


    return metSalesOrderShipmentLoadHeader;
}

public Static void createShipmentLines(METSalesOrderShipmentLoadHeader      _shipmentHeader)
{
    METSalesOrderShipmentLoadLines      metSalesOrderShipmentLoadLines;
    SalesLine                           salesLine;
    InventDim                           inventDim;
    SalesTable                          salesTable;
    WMSOrderTrans                       wmsOrderTrans;
    WMSPickingRoute                     wmsPickingRoute;
    RecordInsertList                    shipLinesRecordInsertList = new RecordInsertList(tableNum(METSalesOrderShipmentLoadLines), false, false, false, false, false);

    while select salesLine
        exists join salesTable
            where salesLine.SalesId == salesTable.SalesId                   &&
                salesTable.CustAccount == _shipmentHeader.CustAccount       &&
                salesTable.METRoute == _shipmentHeader.Route                &&
                salesTable.METRouteStopNum == _shipmentHeader.RouteStopNum  &&
                salesTable.ShippingDateConfirmed == _shipmentHeader.ConfirmedShipDate 
        exists join inventDim
            where inventDim.inventDimId == salesLine.InventDimId            &&
                inventDim.InventLocationId == _shipmentHeader.Warehouse
    {
        metSalesOrderShipmentLoadLines.clear();

        metSalesOrderShipmentLoadLines.ShipmentId       = _shipmentHeader.ShipmentId;
        metSalesOrderShipmentLoadLines.OrderNum         = salesLine.SalesId;
        metSalesOrderShipmentLoadLines.LineNum          = salesLine.LineNum;
        metSalesOrderShipmentLoadLines.ItemId           = salesLine.ItemId;
        metSalesOrderShipmentLoadLines.BackOrder        = salesLine.salesTable().METAllowBackOrders;
        metSalesOrderShipmentLoadLines.SalesOrderStatus = salesLine.SalesStatus;

        select firstonly wmsOrderTrans
            order by CreatedDateTime desc
            where wmsOrderTrans.inventTransId == salesLine.InventTransId;

        metSalesOrderShipmentLoadLines.PickedQty = wmsOrderTrans.qty;
        metSalesOrderShipmentLoadLines.PickingListNum = wmsOrderTrans.wmsPickingRoute().pickingRouteID;
        metSalesOrderShipmentLoadLines.PickingListStatus = wmsOrderTrans.wmsPickingRoute().expeditionStatus;
        metSalesOrderShipmentLoadLines.PickListPostedBy = wmsOrderTrans.wmsPickingRoute().CreatedBy;
        //metSalesOrderShipmentLoadLines.ExtractionStatus = ;

        shipLinesRecordInsertList.add(metSalesOrderShipmentLoadLines);
    }

    shipLinesRecordInsertList.insertDatabase();
}
